css:
.funnel-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d7e3ea;
    background: radial-gradient(1200px 600px at 15% -10%, #16313a 0%, #0d1b22 45%, #091319 100%);
    border-radius: 18px;
    border: 1px solid #1b3640;
}

.funnel-container * {
    box-sizing: border-box;
}

.funnel-header {
    text-align: center;
    padding: 28px 22px 24px;
    background:
        linear-gradient(135deg, rgba(34, 211, 199, 0.10) 0%, rgba(13, 27, 34, 0) 60%),
        repeating-linear-gradient(135deg, rgba(34, 211, 199, 0.05) 0 2px, transparent 2px 9px),
        linear-gradient(160deg, #0e2730 0%, #0b1b22 100%);
    color: #eaf6f4;
    border-radius: 16px;
    margin-bottom: 18px;
    border: 1px solid #1f4651;
    box-shadow: 0 14px 34px rgba(0, 0, 0, 0.45), inset 0 0 0 1px rgba(34, 211, 199, 0.05);
}

.funnel-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
    text-shadow: 0 0 24px rgba(34, 211, 199, 0.30);
}

.funnel-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #5ff0e2;
    background: rgba(34, 211, 199, 0.10);
    border: 1px solid rgba(34, 211, 199, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.funnel-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #aec6cf;
}

.funnel-firms {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.funnel-firm {
    flex: 1;
    background: #0f2630;
    border-radius: 14px;
    padding: 14px 18px;
    border: 1px solid #1d3b45;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.30);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.funnel-firm-lumen { border-left: 5px solid #22d3c7; }
.funnel-firm-rival { border-left: 5px solid #f0913b; }

.funnel-firm-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #e6f6f4;
}

.funnel-firm-lumen .funnel-firm-name { color: #4fe6d9; }
.funnel-firm-rival .funnel-firm-name { color: #f5a85e; }

.funnel-firm-meta {
    font-size: 0.82rem;
    color: #8aa6af;
    line-height: 1.4;
}

.funnel-firm-vs {
    align-self: center;
    font-size: 1.2rem;
    font-weight: 800;
    color: #6f8c95;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.funnel-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb8c0;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.funnel-period-counter #currentDay,
.funnel-period-counter #maxPeriods {
    font-weight: 800;
    color: #22d3c7;
}

.funnel-round-name {
    background: rgba(34, 211, 199, 0.14);
    color: #5ff0e2;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(34, 211, 199, 0.28);
}

.funnel-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #f5a85e;
    background: rgba(240, 145, 59, 0.12);
    border: 1px solid rgba(240, 145, 59, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.funnel-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.funnel-status-card {
    background: linear-gradient(165deg, #112e38 0%, #0d2129 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #1d3b45;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.30);
    border-top: 4px solid #22d3c7;
}

.funnel-card-yield { border-top-color: #22d3c7; }
.funnel-card-ttm { border-top-color: #5aa9e6; }
.funnel-card-roi { border-top-color: #b48cf0; }
.funnel-card-network { border-top-color: #f0913b; }

.funnel-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7f9aa3;
}

.funnel-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eaf6f4;
    font-variant-numeric: tabular-nums;
}

.funnel-card-yield .funnel-value { color: #2fe0d2; }
.funnel-card-ttm .funnel-value { color: #6fb8f0; }
.funnel-card-roi .funnel-value { color: #c2a0f5; }
.funnel-card-network .funnel-value { color: #f6a85e; }

.funnel-sublabel {
    font-size: 0.75rem;
    color: #7f9aa3;
    line-height: 1.35;
}

.funnel-card-network.funnel-network-loss { border-top-color: #ef5d5d; }
.funnel-card-network.funnel-network-loss .funnel-value { color: #ff6b6b; }
.funnel-card-network.funnel-network-win { border-top-color: #2fe0d2; }
.funnel-card-network.funnel-network-win .funnel-value { color: #2fe0d2; }

.funnel-card-ttm.funnel-ttm-good { border-top-color: #2fe0d2; }
.funnel-card-ttm.funnel-ttm-good .funnel-value { color: #2fe0d2; }
.funnel-card-ttm.funnel-ttm-bad { border-top-color: #ef5d5d; }
.funnel-card-ttm.funnel-ttm-bad .funnel-value { color: #ff6b6b; }

.funnel-threat-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0f2630;
    border: 1px solid #1d3b45;
    color: #9fb8c0;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.funnel-threat-bar #threatDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ff6b6b;
    font-weight: 800;
}

.funnel-threat-bar.funnel-threat-low #threatDisplay { color: #2fe0d2; }
.funnel-threat-bar.funnel-threat-mid #threatDisplay { color: #f5a85e; }

.funnel-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #112e38 0%, #0d2129 100%);
    border-left: 5px solid #22d3c7;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #1d3b45;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.28);
}

.funnel-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
    color: #2fe0d2;
}

.funnel-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #eaf6f4;
    margin-bottom: 6px;
}

.funnel-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #b9d0d8;
}

.funnel-briefing-text strong { color: #5ff0e2; }
.funnel-briefing-text em { color: #f5a85e; font-style: italic; }

.funnel-controls {
    background: #0f2630;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #1d3b45;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.28);
}

.funnel-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eaf6f4;
    border-bottom: 2px solid #1d3b45;
    padding-bottom: 8px;
}

.funnel-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c7dde4;
    margin: 14px 0 6px;
}

.funnel-container select,
.funnel-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2a4d59;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0b1f27;
    color: #e6f6f4;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.funnel-container select:focus,
.funnel-container input[type="number"]:focus {
    outline: none;
    border-color: #22d3c7;
    box-shadow: 0 0 0 3px rgba(34, 211, 199, 0.20);
}

.funnel-container select option {
    background-color: #0b1f27;
    color: #e6f6f4;
}

.funnel-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #22d3c7;
}

.funnel-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb8c0;
    margin-top: 4px;
}

.funnel-range-readout span:nth-child(2) {
    color: #2fe0d2;
    font-weight: 800;
}

.funnel-hint {
    font-size: 0.8rem;
    color: #7f9aa3;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.funnel-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.funnel-container .btn-primary {
    background: linear-gradient(135deg, #14998f 0%, #22d3c7 100%);
    border: none;
    color: #042422;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(34, 211, 199, 0.28);
}

.funnel-container .btn-primary:hover {
    filter: brightness(1.08);
}

.funnel-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2a4d59;
    color: #9fb8c0;
    background: transparent;
}

.funnel-container .btn-outline-secondary:hover {
    color: #e6f6f4;
    border-color: #3a6573;
}

.funnel-coach {
    background: linear-gradient(160deg, #0e2730 0%, #0a1a20 100%);
    color: #cfe6e1;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #1f4651;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.34);
}

.funnel-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f5a85e;
    margin-bottom: 8px;
}

.funnel-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.funnel-coach-body strong { color: #5ff0e2; }
.funnel-coach-body em { color: #f5a85e; font-style: italic; }

.funnel-history,
.funnel-chart {
    background: #0f2630;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #1d3b45;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.28);
}

.funnel-history h3,
.funnel-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eaf6f4;
}

.funnel-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #b9d0d8;
}

.funnel-container table#usfHistoryTable th {
    background: #0b2027;
    color: #5ff0e2;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1d3b45;
}

.funnel-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #15303a;
    color: #b9d0d8;
}

.funnel-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0d232b;
}

.funnel-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .funnel-container {
        padding: 14px;
    }
    .funnel-header h1 {
        font-size: 1.7rem;
    }
    .funnel-firms {
        flex-direction: column;
    }
    .funnel-firm-vs {
        transform: rotate(90deg);
    }
    .funnel-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .funnel-value {
        font-size: 2rem;
    }
    .funnel-clock {
        margin-left: 0;
    }
    .funnel-period-counter {
        font-size: 0.88rem;
    }
    .funnel-threat-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .funnel-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ===== Completion debrief (v1.1.0) — namespaced .otf-cm-*, append-only. Dark teal palette. ===== */
.otf-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #d7e3ea;
    background: radial-gradient(900px 420px at 15% -10%, #16313a 0%, #0d1b22 50%, #091319 100%);
    border: 1px solid rgba(47, 224, 210, 0.20); border-radius: 16px; padding: 22px 24px 24px; max-width: 720px; margin: 8px auto;
    box-shadow: 0 14px 36px rgba(3, 10, 14, 0.55); }
.otf-cm-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
    border-bottom: 1px solid rgba(47, 224, 210, 0.18); padding-bottom: 14px; margin-bottom: 16px; }
.otf-cm-verdict { font-size: 1.5rem; font-weight: 800; letter-spacing: -0.3px; line-height: 1.15; }
.otf-cm-good .otf-cm-verdict { color: #2fe0d2; }
.otf-cm-mid  .otf-cm-verdict { color: #f5a85e; }
.otf-cm-bad  .otf-cm-verdict { color: #ff8a8a; }
.otf-cm-score { display: flex; align-items: baseline; gap: 6px; white-space: nowrap; }
.otf-cm-score-num { font-size: 2.1rem; font-weight: 800; color: #eaf6f4; }
.otf-cm-score-max { font-size: 1rem; color: #7f9aa3; }
.otf-cm-grade { margin-left: 10px; font-size: 0.82rem; font-weight: 700; color: #bff6f1;
    background: rgba(47, 224, 210, 0.14); border: 1px solid rgba(47, 224, 210, 0.30); padding: 3px 10px; border-radius: 999px; }
.otf-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 16px; }
.otf-cm-kpi { background: rgba(29, 59, 69, 0.55); border: 1px solid rgba(47, 224, 210, 0.16); border-radius: 12px; padding: 12px 10px; text-align: center; }
.otf-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #eaf6f4; }
.otf-cm-kpi-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.6px; color: #7f9aa3; margin-top: 4px; }
.otf-cm-kpi.otf-cm-ok { border-color: rgba(47, 224, 210, 0.5); box-shadow: inset 0 0 0 1px rgba(47, 224, 210, 0.14); }
.otf-cm-kpi.otf-cm-no { border-color: rgba(255, 138, 138, 0.42); }
.otf-cm-gates-h, .otf-cm-insights-h { font-size: 0.74rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f5a85e; margin: 6px 0 8px; }
.otf-cm-gates { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.otf-cm-chip { font-size: 0.8rem; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.otf-cm-chip-ok { color: #052622; background: #2fe0d2; }
.otf-cm-chip-no { color: #ffd9d9; background: rgba(255, 138, 138, 0.16); border-color: rgba(255, 138, 138, 0.42); }
.otf-cm-insights { margin: 0; padding-left: 18px; }
.otf-cm-insights li { font-size: 0.92rem; line-height: 1.5; color: #c9d8e0; margin-bottom: 8px; }
@media (max-width: 560px) { .otf-cm-kpis { grid-template-columns: repeat(2, 1fr); } .otf-cm-head { flex-direction: column; align-items: flex-start; } }

