(function() {
    'use strict';

    class OpeningTheFunnelAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Opening the Funnel`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Lumen Coatings NV). ----
            this.RD_BUDGET = 19.2;          // €19.2M annual R&D envelope
            this.START_TTM = 38;            // average time-to-market (months)
            this.BENCH_TTM = 24;            // industry benchmark (months)
            this.START_EXPOSURE = 78;       // closed-model exposure index 0–100 (lower safer)
            this.TRITON_REVENUE = 22;       // €22M projected (yrs 1–3)
            this.TRITON_SUNK = 8.4;         // €8.4M already sunk
            this.TRITON_FINISH = 3.6;       // €3.6M to finish internally
            this.TRITON_LATE_REV = 9;       // ~€9M residual if 14 months late
            this.ENZYME_UPFRONT = 2.8;      // €2.8M inbound licence upfront
            this.FAIR_ROYALTY = 6;          // 6% typical for enabling tech
            this.RIVAL_OUTLIC = 4;          // AquaShield earns €4M/yr out-licensing
            this.DORMANT = 98;              // ~98 dormant patents

            // ---- Concept truths (the modelled, strategy-led answers). ----
            this.TRUE_TRITON = `license`;
            this.TRUE_MODE = `balanced`;
            this.TRUE_PITCH = `scalpel`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    yield: 0,                       // external-idea yield (%)
                    ttm: this.START_TTM,            // time-to-market (months)
                    roi: 1.0,                       // R&D ROI multiple
                    value: 0,                       // net €M value realised this cycle
                    exposure: this.START_EXPOSURE,  // closed-model exposure 0–100 (lower safer)

                    // Sticky, run-defining penalty flags (set when an error is committed).
                    closedRun: false,               // defaulted to closed on Tritón / kept budget 100% internal
                    hoardRun: false,                // refused to out-license any dormant IP
                    leakRun: false,                 // opened without protective terms (the same tech reaches the rival)
                    coreLostRun: false,             // out-licensed the anti-corrosion core (fire sale)
                    escalationMissed: false,        // ignored AquaShield's bid; lost the spin-out
                    noModelRun: false,              // no operating model / wrong KPI commitment
                    tritonLicensed: false,          // signed the inbound enzyme licence

                    yieldHistory: [0],
                    ttmHistory: [this.START_TTM],
                    roiHistory: [1.0],
                    valueHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    front: `fine`,
                    side: `protect`,
                    triton: `closed`,
                    culture: 30,
                    mode: `closed`,
                    partner: `none`,
                    tritonDeal: `no`,
                    internal: 100,
                    exclusivity: `nonexclusive`,
                    outbound: `none`,
                    core: `all_core`,
                    escalation: `ignore`,
                    royalty: 6,
                    governance: `none`,
                    kpi: `revenue_only`,
                    pitch: `closed_pride`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frontInput`);
                const si = document.getElementById(`sideInput`);
                const tr = document.getElementById(`tritonInput`);
                const cu = document.getElementById(`cultureInput`);
                if (fr) decisions.front = fr.value;
                if (si) decisions.side = si.value;
                if (tr) decisions.triton = tr.value;
                if (cu) decisions.culture = parseInt(cu.value, 10);
                if (!Number.isFinite(decisions.culture) || decisions.culture < 0 || decisions.culture > 100) {
                    warn(`warn_culture_range`); return false;
                }
            } else if (round === 2) {
                const mo = document.getElementById(`modeInput`);
                const pa = document.getElementById(`partnerInput`);
                const td = document.getElementById(`tritonDealInput`);
                const it = document.getElementById(`internalInput`);
                if (mo) decisions.mode = mo.value;
                if (pa) decisions.partner = pa.value;
                if (td) decisions.tritonDeal = td.value;
                if (it) decisions.internal = parseInt(it.value, 10);
                if (!Number.isFinite(decisions.internal) || decisions.internal < 0 || decisions.internal > 100) {
                    warn(`warn_internal_range`); return false;
                }
            } else if (round === 3) {
                const ex = document.getElementById(`exclusivityInput`);
                const ob = document.getElementById(`outboundInput`);
                const co = document.getElementById(`coreInput`);
                const es = document.getElementById(`escalationInput`);
                const ro = document.getElementById(`royaltyInput`);
                if (ex) decisions.exclusivity = ex.value;
                if (ob) decisions.outbound = ob.value;
                if (co) decisions.core = co.value;
                if (es) decisions.escalation = es.value;
                if (ro) decisions.royalty = parseFloat(ro.value);
                if (!Number.isFinite(decisions.royalty) || decisions.royalty < 0 || decisions.royalty > 20) {
                    warn(`warn_royalty_range`); return false;
                }
            } else if (round === 4) {
                const go = document.getElementById(`governanceInput`);
                const kp = document.getElementById(`kpiInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (go) decisions.governance = go.value;
                if (kp) decisions.kpi = kp.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let yieldDelta = 0, ttmDelta = 0, roiDelta = 0, valueDelta = 0, exposureDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the funnel + the Tritón call (Common Error #1: defaulting to closed).
                switch (d.front) {
                    case `scouting`: exposureDelta -= 8; yieldDelta += 2; coachKey = `coach_r1_front_good`; break;
                    case `minor`: exposureDelta += 2; coachKey = `coach_r1_front_minor`; break;
                    case `fine`: exposureDelta += 6; coachKey = `coach_r1_front_fine`; break;
                }

                switch (d.side) {
                    case `dormant`: exposureDelta -= 8; coachKey = `coach_r1_side_good`; break;
                    case `legal`: exposureDelta += 4; coachKey = `coach_r1_side_legal`; break;
                    case `protect`: exposureDelta += 7; ds.hoardRun = true; coachKey = `coach_r1_side_protect`; break;
                }

                switch (d.triton) {
                    case `license`:
                        // The speed lever — launch in 8 months, capture the first-mover share.
                        yieldDelta += 10; ttmDelta -= 8; exposureDelta -= 12; valueDelta += 4;
                        coachKey = `coach_r1_triton_license`;
                        break;
                    case `kill`:
                        // Honest, but cedes the €22M segment entirely; no speed win.
                        ttmDelta -= 2; exposureDelta -= 2; valueDelta -= 1;
                        coachKey = `coach_r1_triton_kill`;
                        break;
                    case `closed`:
                        // HEADLINE ANTI-PATTERN — finish in-house, arrive 14 months late.
                        ds.closedRun = true;
                        ttmDelta += 2; exposureDelta += 12; valueDelta -= 2;
                        coachKey = `coach_r1_triton_closed`;
                        break;
                }

                // Confronting the NIH culture early lowers exposure (absorptive capacity).
                if (d.culture >= 60) { exposureDelta -= 6; yieldDelta += 1; }
                else if (d.culture <= 20) { exposureDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r1_nih`; }

                summaryKey = (d.front === `scouting` && d.side === `dormant` && d.triton === `license`) ? `sum_r1_good` :
                             (d.triton === `closed` ? `sum_r1_closed` : `sum_r1_weak`);
            } else if (round === 2) {
                // Openness mode + partner + the Tritón inbound deal (Common Errors #1 & #2).
                const internalShare = d.internal / 100;

                switch (d.mode) {
                    case `balanced`:
                        yieldDelta += 9; roiDelta += 0.25; exposureDelta -= 14; valueDelta += 2;
                        coachKey = `coach_r2_balanced`;
                        break;
                    case `closed`:
                        ds.closedRun = true;
                        exposureDelta += 12; roiDelta -= 0.10; coachKey = `coach_r2_closed`;
                        break;
                    case `outsource`:
                        // Over-opening at the budget level hollows absorptive capacity.
                        yieldDelta += 5; exposureDelta -= 2; roiDelta -= 0.15;
                        coachKey = `coach_r2_outsource`;
                        break;
                }

                // Budget rebalancing: ~60–80% internal is the open-but-capable zone.
                if (internalShare >= 0.95) {
                    ds.closedRun = true; exposureDelta += 8; yieldDelta -= 4;
                    if (coachKey === `coach_default`) coachKey = `coach_r2_allinternal`;
                } else if (internalShare <= 0.25) {
                    exposureDelta += 4; roiDelta -= 0.20; yieldDelta -= 2;
                    if (coachKey === `coach_r2_balanced`) coachKey = `coach_r2_hollow`;
                } else if (internalShare >= 0.55 && internalShare <= 0.8) {
                    roiDelta += 0.15; exposureDelta -= 4;
                }

                // Lead partner — capability vs leakage vs renewable pipeline.
                switch (d.partner) {
                    case `spinout`: yieldDelta += 6; ttmDelta -= 4; exposureDelta -= 6; valueDelta += 2; break;
                    case `shipyard`: yieldDelta += 4; ttmDelta -= 3; exposureDelta -= 3; break;
                    case `accelerator`: yieldDelta += 2; exposureDelta -= 5; roiDelta += 0.05; break; // renewable deal-flow
                    case `cro`: ttmDelta -= 2; roiDelta -= 0.05; exposureDelta += 1; break;            // capacity, no ideas
                    case `none`: exposureDelta += 6; yieldDelta -= 2; if (coachKey === `coach_r2_balanced`) coachKey = `coach_r2_nopartner`; break;
                }

                // The Tritón inbound deal becomes concrete.
                if (d.tritonDeal === `yes`) {
                    ds.tritonLicensed = true;
                    yieldDelta += 6; ttmDelta -= 6; valueDelta += 3; exposureDelta -= 6;
                    if (d.partner !== `spinout`) { coachKey = `coach_r2_deal_nospinout`; valueDelta -= 1; }
                    else if (coachKey === `coach_r2_balanced`) coachKey = `coach_r2_deal_yes`;
                } else {
                    // Refusing the deal here re-commits to the closed/late path.
                    ds.closedRun = true;
                    valueDelta -= 2; ttmDelta += 2; exposureDelta += 8;
                    if (coachKey === `coach_default`) coachKey = `coach_r2_deal_no`;
                }

                summaryKey = (d.mode === `balanced` && d.tritonDeal === `yes` && d.partner === `spinout`) ? `sum_r2_good` :
                             (d.mode === `closed` || d.tritonDeal === `no` ? `sum_r2_closed` :
                             (d.mode === `outsource` ? `sum_r2_outsource` : `sum_r2_weak`));
            } else if (round === 3) {
                // IP & deal terms — the heart of value capture (Common Errors #3 & #4).
                // (a) Inbound exclusivity & field-of-use.
                switch (d.exclusivity) {
                    case `exclusive_marine`:
                        exposureDelta -= 8; valueDelta += 3; roiDelta += 0.15; break;
                    case `exclusive_all`:
                        // Locks it up but over-pays for fields Lumen won't use.
                        exposureDelta -= 4; valueDelta -= 1; coachKey = `coach_r3_exclusive_all`; break;
                    case `nonexclusive`:
                        // OPENING WITHOUT TERMS — the same enzyme can reach AquaShield.
                        ds.leakRun = true; exposureDelta += 10; valueDelta -= 3;
                        coachKey = `coach_r3_nonexclusive`; break;
                }

                // (b) Outbound plan for the ~98 dormant patents.
                switch (d.outbound) {
                    case `periphery`:
                        ds.hoardRun = false;
                        yieldDelta += 5; valueDelta += this.RIVAL_OUTLIC; roiDelta += 0.30; exposureDelta -= 10;
                        coachKey = `coach_r3_outbound_periphery`; break;
                    case `core`:
                        // OVER-OPENING — out-licensing the anti-corrosion core.
                        ds.coreLostRun = true; ds.hoardRun = false;
                        valueDelta += 2; exposureDelta += 6; roiDelta -= 0.10;
                        coachKey = `coach_r3_outbound_core`; break;
                    case `none`:
                        // HOARDING — 98 dormant patents keep earning zero.
                        ds.hoardRun = true; exposureDelta += 6; valueDelta -= 1;
                        coachKey = `coach_r3_outbound_none`; break;
                }

                // (c) Core-vs-periphery boundary.
                switch (d.core) {
                    case `defend_core`: exposureDelta -= 8; valueDelta += 1; roiDelta += 0.10; break;
                    case `all_core`: ds.hoardRun = true; exposureDelta += 5; coachKey = (coachKey === `coach_default`) ? `coach_r3_allcore` : coachKey; break;
                    case `all_periphery`: ds.coreLostRun = true; exposureDelta += 7; coachKey = `coach_r3_allperiphery`; break;
                }

                // The escalation event — AquaShield's same-day bid for the spin-out.
                switch (d.escalation) {
                    case `option`:
                        valueDelta += 2; exposureDelta -= 6; yieldDelta += 2;
                        if (coachKey === `coach_default`) coachKey = `coach_r3_escalation_option`; break;
                    case `walk`:
                        ds.escalationMissed = true; exposureDelta += 8; yieldDelta -= 3; valueDelta -= 1;
                        coachKey = `coach_r3_escalation_walk`; break;
                    case `ignore`:
                        ds.escalationMissed = true; exposureDelta += 12; yieldDelta -= 5; valueDelta -= 2;
                        coachKey = `coach_r3_escalation_ignore`; break;
                }

                // Royalty negotiation — a fair rate keeps the partner renewable.
                if (d.royalty >= 4 && d.royalty <= 8) { roiDelta += 0.10; exposureDelta -= 2; }
                else if (d.royalty < 2) { exposureDelta += 4; valueDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r3_royalty_low`; }
                else if (d.royalty > 12) { valueDelta -= 2; roiDelta -= 0.10; if (coachKey === `coach_default`) coachKey = `coach_r3_royalty_high`; }

                summaryKey = (d.exclusivity === `exclusive_marine` && d.outbound === `periphery` && d.core === `defend_core` && d.escalation === `option`) ? `sum_r3_good` :
                             (d.exclusivity === `nonexclusive` ? `sum_r3_leak` :
                             (d.outbound === `core` || d.core === `all_periphery` ? `sum_r3_firesale` :
                             (d.outbound === `none` ? `sum_r3_hoard` : `sum_r3_weak`)));
            } else if (round === 4) {
                // Operating model + governance + KPIs + the board pitch (Common Error #5).
                switch (d.governance) {
                    case `full`: exposureDelta -= 12; yieldDelta += 4; roiDelta += 0.15; coachKey = `coach_r4_gov_full`; break;
                    case `scouting_only`: exposureDelta -= 4; yieldDelta += 2; coachKey = `coach_r4_gov_scouting`; break;
                    case `none`: ds.noModelRun = true; exposureDelta += 10; coachKey = `coach_r4_gov_none`; break;
                }

                switch (d.kpi) {
                    case `open_set`: exposureDelta -= 6; roiDelta += 0.10; break;
                    case `revenue_only`: ds.noModelRun = true; exposureDelta += 5; coachKey = (coachKey === `coach_default`) ? `coach_r4_kpi_revenue` : coachKey; break;
                    case `patents_filed`: ds.noModelRun = true; exposureDelta += 7; coachKey = (coachKey === `coach_default`) ? `coach_r4_kpi_patents` : coachKey; break;
                }

                switch (d.pitch) {
                    case `scalpel`:
                        yieldDelta += 3; roiDelta += 0.15; exposureDelta -= 8;
                        if (d.governance === `full`) coachKey = `coach_r4_scalpel`;
                        break;
                    case `closed_pride`:
                        ds.closedRun = true; exposureDelta += 9; roiDelta -= 0.10;
                        coachKey = `coach_r4_closed_pride`; break;
                    case `fire_sale`:
                        ds.coreLostRun = true; exposureDelta += 7; valueDelta -= 1;
                        coachKey = `coach_r4_fire_sale`; break;
                }

                if (d.conviction >= 60) { exposureDelta -= 4; roiDelta += 0.05; }
                else if (d.conviction <= 25) { exposureDelta += 4; }

                summaryKey = (d.governance === `full` && d.kpi === `open_set` && d.pitch === `scalpel`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.yield = Math.max(0, Math.min(100, Math.round(ds.yield + yieldDelta)));
            ds.ttm = Math.max(this.BENCH_TTM - 4, Math.min(48, Math.round((ds.ttm + ttmDelta) * 10) / 10));
            ds.roi = Math.max(0.2, Math.min(3.5, Math.round((ds.roi + roiDelta) * 100) / 100));
            ds.value = Math.round((ds.value + valueDelta) * 10) / 10;
            ds.exposure = Math.max(0, Math.min(100, Math.round(ds.exposure + exposureDelta)));

            // ---- Run-defining flags GATE the KPIs (sticky caps, not soft deltas). ----
            // Defaulting to closed caps the speed and yield wins for the whole run.
            if (ds.closedRun) {
                ds.yield = Math.min(ds.yield, 18);
                ds.ttm = Math.max(ds.ttm, 34);
                ds.roi = Math.min(ds.roi, 1.05);
            }
            // Opening without terms: the enzyme reaches the rival — value capture collapses.
            if (ds.leakRun) {
                ds.value = Math.min(ds.value, 3);
                ds.roi = Math.min(ds.roi, 1.25);
            }
            // Over-opening the core: the licensee becomes a competitor — ROI and value capped.
            if (ds.coreLostRun) {
                ds.roi = Math.min(ds.roi, 1.15);
                ds.value = Math.min(ds.value, 5);
                ds.exposure = Math.max(ds.exposure, 45);
            }
            // Hoarding all IP: the dormant €4M/yr stays unrealised — yield and value capped.
            if (ds.hoardRun) {
                ds.yield = Math.min(ds.yield, 28);
                ds.value = Math.min(ds.value, 6);
            }
            // Missing the escalation: inbound door slams — exposure floor stays high.
            if (ds.escalationMissed) {
                ds.exposure = Math.max(ds.exposure, 40);
                ds.yield = Math.min(ds.yield, 26);
            }
            // No operating model: openness reverts to closed — exposure floor.
            if (ds.noModelRun) {
                ds.exposure = Math.max(ds.exposure, 38);
            }

            ds.yieldHistory.push(ds.yield);
            ds.ttmHistory.push(ds.ttm);
            ds.roiHistory.push(ds.roi);
            ds.valueHistory.push(ds.value);

            // ---- Persist the composite where the gradebook / AGS + history readers look ----
            // Framework contract (results_utils.php): express_resolveDomainScore reads
            // domainState.performance.overallScore first, then a top-level score; and
            // express_extractHistory reads history[].domainState.performance.overallScore.
            // addToHistory() deep-clones domainState into each snapshot, so writing it here lands
            // the per-period score in the gradebook by construction.
            const composite = this._composite(ds);
            ds.performance = { overallScore: composite, grade: this._gradeLetter(composite) };
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                yield: ds.yield,
                yieldDelta: Math.round(yieldDelta),
                ttm: ds.ttm,
                ttmDelta: Math.round(ttmDelta * 10) / 10,
                roi: ds.roi,
                roiDelta: Math.round(roiDelta * 100) / 100,
                value: ds.value,
                valueDelta: Math.round(valueDelta * 10) / 10,
                exposure: ds.exposure,
                score: composite,
                overallScore: composite,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _exposureLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 55) return t(`exposure_high`);
            if (v >= 30) return t(`exposure_mid`);
            return t(`exposure_low`);
        }

        _fmtRoi(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(2);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `×`;
        }

        _fmtValue(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) * 10) / 10;
            const s = n.toFixed(1);
            const num = (lang === `es` ? s.replace(`.`, `,`) : s);
            return `€${num}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`yieldDisplay`, `domainState.yield`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`ttmDisplay`, `domainState.ttm`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.funnel-card-ttm`);
                if (card) {
                    card.classList.toggle(`funnel-ttm-good`, n <= self.BENCH_TTM + 2);
                    card.classList.toggle(`funnel-ttm-bad`, n >= 36);
                }
                const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
                return `${Math.round(n)} ${lang === `es` ? `m` : `mo`}`;
            });

            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => self._fmtRoi(Number(v)));

            uiManager.bind(`networkDisplay`, `domainState.value`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.funnel-card-network`);
                if (card) {
                    card.classList.toggle(`funnel-network-loss`, n < 0);
                    card.classList.toggle(`funnel-network-win`, n >= 8);
                }
                return self._fmtValue(n);
            });

            uiManager.bind(`threatDisplay`, `domainState.exposure`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.funnel-threat-bar`);
                if (bar) {
                    bar.classList.toggle(`funnel-threat-low`, n < 30);
                    bar.classList.toggle(`funnel-threat-mid`, n >= 30 && n < 55);
                }
                return self._exposureLabel(n);
            });

            // Culture slider readout.
            const cu = document.getElementById(`cultureInput`);
            const cuReadout = document.getElementById(`cultureReadout`);
            if (cu && cuReadout) {
                cuReadout.textContent = cu.value;
                cu.addEventListener(`input`, function() { cuReadout.textContent = cu.value; });
            }

            // Internal-share slider readout.
            const it = document.getElementById(`internalInput`);
            const itReadout = document.getElementById(`internalReadout`);
            if (it && itReadout) {
                itReadout.textContent = it.value;
                it.addEventListener(`input`, function() { itReadout.textContent = it.value; });
            }
        }

        // Composite — the VERBATIM v1.0.0 formula, factored out so calculateResults() can persist
        // the same value every period that getPerformanceSummary() reports at completion. Scoring
        // is unchanged; this is a refactor, not a re-tune. (The run-defining flags cap the
        // underlying KPIs in calculateResults, so their effect is already baked into ds.)
        _composite(ds) {
            const yieldV = Math.round(ds.yield);
            const ttm = Math.round(ds.ttm);
            const roi = Math.round(ds.roi * 100) / 100;
            const value = Math.round(ds.value * 10) / 10;
            const ttmScore = Math.max(0, Math.min(100, (this.START_TTM - ttm) / (this.START_TTM - this.BENCH_TTM) * 100));
            const roiScore = Math.max(0, Math.min(100, (roi - 0.8) / (2.0 - 0.8) * 100));
            const valueScore = Math.max(0, Math.min(100, (value / 14) * 100));
            return Math.round(yieldV * 0.28 + ttmScore * 0.24 + roiScore * 0.24 + valueScore * 0.24);
        }

        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 70) return `B`;
            if (c >= 58) return `C`;
            if (c >= 45) return `D`;
            return `F`;
        }

        // Localize the internal (English) verdict tier id. The English id stays the stable key the
        // scoring logic keys on; the label is resolved for display only.
        _gradeLabel(id) {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const map = {
                'Funnel Opened':        `verdict_opened`,
                'Funnel Stayed Closed': `verdict_stayed_closed`,
                'Defaulted to Closed':  `verdict_defaulted`,
                'Core Sold Off':        `verdict_core_sold`,
                'Opened Without Terms': `verdict_no_terms`,
                'Dormant IP Hoarded':   `verdict_hoarded`,
                'Partially Opened':     `verdict_partial`
            };
            return map[id] ? t(map[id]) : id;
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, fallback) => (t ? t(k) : fallback);
            return {
                funnelChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_yield`, `External-idea yield (%)`),
                                data: [],
                                borderColor: `#22d3c7`,
                                backgroundColor: `rgba(34,211,199,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#22d3c7`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_ttm`, `Time-to-market (months)`),
                                data: [],
                                borderColor: `#5aa9e6`,
                                backgroundColor: `rgba(90,169,230,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#5aa9e6`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_roi`, `R&D ROI (×10)`),
                                data: [],
                                borderColor: `#b48cf0`,
                                backgroundColor: `rgba(180,140,240,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b48cf0`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#9fb8c0`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 50, position: `left`,
                                ticks: { color: `#7f9aa3` }, grid: { color: `rgba(159,184,192,0.10)` },
                                title: { display: true, text: L(`chart_axis_units`, `months · % · ROI×10`), color: `#7f9aa3` }
                            },
                            x: {
                                ticks: { color: `#7f9aa3` }, grid: { color: `rgba(159,184,192,0.06)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#7f9aa3` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.yieldHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // ROI is a small multiple — scale ×10 to share the months/percent axis.
            const roiScaled = ds.roiHistory.map((v) => Math.round(v * 10));
            return {
                funnelChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.yieldHistory.map((v) => Math.round(v)) },
                        { data: ds.ttmHistory.map((v) => Math.round(v)) },
                        { data: roiScaled }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const yieldV = Math.round(ds.yield);
            const ttm = Math.round(ds.ttm);
            const roi = Math.round(ds.roi * 100) / 100;
            const value = Math.round(ds.value * 10) / 10;
            const exposure = Math.round(ds.exposure);

            // KPI gates (the modelled open-innovation turnaround).
            const yieldGood = yieldV >= 30;          // open-innovation goal
            const fastGood = ttm <= 26;              // near the 24-month benchmark
            const roiGood = roi >= 1.3;
            const valueGood = value >= 8;
            const open = exposure < 30;

            // Any run-defining error blocks the top verdict.
            const cleanRun = !ds.closedRun && !ds.leakRun && !ds.coreLostRun &&
                             !ds.hoardRun && !ds.escalationMissed && !ds.noModelRun;

            // Composite: yield, speed (inverted ttm), roi, value. Shares the _composite(ds) helper
            // that calculateResults() persists every period, so the completion composite == the
            // last period's persisted score by construction.
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.closedRun) pattern = `closed`;
            else if (ds.coreLostRun) pattern = `firesale`;
            else if (ds.leakRun) pattern = `leak`;
            else if (ds.hoardRun) pattern = `hoard`;
            else if (cleanRun && yieldGood && fastGood && open) pattern = `open`;

            let performance = `Funnel Stayed Closed`;
            if (cleanRun && yieldGood && fastGood && roiGood && valueGood && open && composite >= 72) {
                performance = `Funnel Opened`;
            } else if (ds.closedRun) {
                performance = `Defaulted to Closed`;
            } else if (ds.coreLostRun) {
                performance = `Core Sold Off`;
            } else if (ds.leakRun) {
                performance = `Opened Without Terms`;
            } else if (ds.hoardRun) {
                performance = `Dormant IP Hoarded`;
            } else if (composite >= 55) {
                performance = `Partially Opened`;
            }

            const insights = [];
            if (performance === `Funnel Opened`) insights.push(window.mySimulation.t(`insight_open`));
            else if (pattern === `closed`) insights.push(window.mySimulation.t(`insight_closed`));
            else if (pattern === `firesale`) insights.push(window.mySimulation.t(`insight_firesale`));
            else if (pattern === `leak`) insights.push(window.mySimulation.t(`insight_leak`));
            else if (pattern === `hoard`) insights.push(window.mySimulation.t(`insight_hoard`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.escalationMissed) insights.push(window.mySimulation.t(`insight_escalation`));
            if (ds.noModelRun) insights.push(window.mySimulation.t(`insight_nomodel`));
            if (!ds.tritonLicensed && ds.closedRun) insights.push(window.mySimulation.t(`insight_triton_lost`));
            if (!yieldGood && !ds.closedRun) insights.push(window.mySimulation.t(`insight_yield_low`));

            return {
                yield: yieldV,
                ttm: ttm,
                roi: roi,
                value: value,
                exposure: exposure,
                yieldGood: yieldGood,
                fastGood: fastGood,
                roiGood: roiGood,
                valueGood: valueGood,
                cleanRun: cleanRun,
                open: open,
                pattern: pattern,
                composite: composite,
                grade: this._gradeLetter(composite),
                performance: this._gradeLabel(performance),
                performanceId: performance,
                insights: insights
            };
        }

        // Rich, localized board debrief. Without this override the framework falls through to the
        // base "You completed N periods." stub and discards the composite, verdict, KPIs and
        // insights this sim already computes. Self-contained, namespaced (.otf-cm-*) markup.
        formatCompletionMessage(summary) {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = summary || {};
            const esc = (v) => String(v == null ? `` : v).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;

            const composite = Math.round(Number(s.composite) || 0);
            const grade = esc(s.grade || this._gradeLetter(composite));
            const verdict = esc(s.performance || ``);
            const id = s.performanceId || ``;
            const tone = (id === `Funnel Opened`) ? `good` : (id === `Partially Opened`) ? `mid` : `bad`;

            const ttmStr = Math.round(Number(s.ttm) || 0) + ` ` + (lang === `es` ? `m` : `mo`);
            const kpi = (label, value, ok) =>
                `<div class="otf-cm-kpi ${ok ? `otf-cm-ok` : `otf-cm-no`}"><div class="otf-cm-kpi-val">${value}</div><div class="otf-cm-kpi-lbl">${label}</div></div>`;
            const chip = (ok, label) =>
                `<span class="otf-cm-chip ${ok ? `otf-cm-chip-ok` : `otf-cm-chip-no`}">${ok ? `✓` : `✕`} ${label} · ${ok ? esc(t(`cm_met`)) : esc(t(`cm_missed`))}</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightsHtml = insights.length
                ? `<ul class="otf-cm-insights">` + insights.map((x) => `<li>${esc(x)}</li>`).join(``) + `</ul>`
                : ``;

            return `
                <div class="otf-cm otf-cm-${tone}">
                    <div class="otf-cm-head">
                        <div class="otf-cm-verdict">${verdict}</div>
                        <div class="otf-cm-score"><span class="otf-cm-score-num">${composite}</span><span class="otf-cm-score-max">/100</span><span class="otf-cm-grade">${esc(t(`cm_grade`))} ${grade}</span></div>
                    </div>
                    <div class="otf-cm-kpis">
                        ${kpi(esc(t(`cm_kpi_yield`)), Math.round(Number(s.yield) || 0) + `%`, !!s.yieldGood)}
                        ${kpi(esc(t(`cm_kpi_ttm`)), ttmStr, !!s.fastGood)}
                        ${kpi(esc(t(`cm_kpi_roi`)), this._fmtRoi(Number(s.roi) || 0), !!s.roiGood)}
                        ${kpi(esc(t(`cm_kpi_value`)), this._fmtValue(Number(s.value) || 0), !!s.valueGood)}
                    </div>
                    <div class="otf-cm-gates-h">${esc(t(`cm_gates_heading`))}</div>
                    <div class="otf-cm-gates">
                        ${chip(!!s.yieldGood, esc(t(`cm_gate_yield`)))}
                        ${chip(!!s.fastGood, esc(t(`cm_gate_ttm`)))}
                        ${chip(!!s.open, esc(t(`cm_gate_open`)))}
                        ${chip(!!s.cleanRun, esc(t(`cm_gate_clean`)))}
                    </div>
                    <div class="otf-cm-insights-h">${esc(t(`cm_insights_heading`))}</div>
                    ${insightsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.closedRun) return window.mySimulation.t(`hint_closed`);
            if (ds.leakRun) return window.mySimulation.t(`hint_leak`);
            if (ds.coreLostRun) return window.mySimulation.t(`hint_core`);
            if (ds.escalationMissed && state.currentPeriod >= 3) return window.mySimulation.t(`hint_escalation`);
            if (ds.hoardRun && state.currentPeriod >= 3) return window.mySimulation.t(`hint_hoard`);
            if (ds.exposure >= 55) return window.mySimulation.t(`hint_exposure`);
            if (ds.yield >= 30 && ds.ttm <= 26 && ds.exposure < 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.yield`, label: `Yield`, i18nKey: `col_yield`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.ttm`, label: `TTM`, i18nKey: `col_ttm`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.roi`, label: `ROI`, i18nKey: `col_roi`, formatter: (v) => self._fmtRoi(Number(v)) },
                { key: `results.value`, label: `Value`, i18nKey: `col_value`, formatter: (v) => self._fmtValue(Number(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

